  const panes = qsa("[data-step-pane]", wizard);

  const btnPrev = qs("[data-disc-prev]", wizard);
  const btnNext = qs("[data-disc-next]", wizard);
  const btnFinish = qs("[data-disc-finish]", wizard);

  const progressEl = qs("#discProgress", wizard);

