function positionToPointer(clientY) {
  const { li, ul, ph, grabDy, listRect } = active;
  // Convert clientY into list-local coords (relative to the list box)
  let localY = clientY - listRect.top - grabDy;
  // Auto-scroll the list when the pointer is near its edges
  if (clientY > listRect.bottom - 60) ul.scrollTop += 10;
  else if (clientY < listRect.top + 60) ul.scrollTop -= 10;
  localY = clientY - listRect.top - grabDy;
  // Clamp inside the list content area
  const maxTop = Math.max(0, ul.scrollHeight - li.offsetHeight);
  const top = Math.max(0, Math.min(localY, maxTop));
  li.style.top = top + "px";

  // Determine the row that should sit under the pointer and insert the ghost accordingly
  const centerLocal = top + li.offsetHeight / 2;
  const centerClient = listRect.top + centerLocal;
  let target = null;
  const rows = Array.from(ul.children).filter(x => x !== ph);
  for (let i = 0; i < rows.length; i++) {
    if (centerClient < rows[i].getBoundingClientRect().top + rows[i].getBoundingClientRect().height / 2) {
      target = rows[i];
      break;
    }
  }
  if (target !== ph.nextSibling && target !== ul.lastElementChild) {
    ul.insertBefore(ph, target || null);
  } else if (target === null && ph.nextSibling) {
    ul.appendChild(ph);
  }
}

