function positionToPointer(clientY) {
  const { li, ul, ph, grabDy, listRect } = active;
  // Convert clientY into list-local coords
  let top = clientY - grabDy - (listRect.top + ul.scrollTop) ;
  // Clamp so the item stays within the list viewport
  const maxTop = Math.max(0, ul.scrollHeight - li.offsetHeight);
  top = Math.max(0, Math.min(top, maxTop));
  // Keep the list scrolled under the pointer for a natural feel
  if (clientY > listRect.bottom - 60) ul.scrollTop += 8;
  else if (clientY < listRect.top + 60) ul.scrollTop -= 8;

  li.style.top = (top + ul.scrollTop) + "px";

  // Determine the row that should sit under the pointer and insert the ghost accordingly
  const next = hitRowIn(ul, clientY + li.offsetHeight / 2);
  const wantBefore = next || ul.lastElementChild;
  const currentPlaceholderPosition = ph.nextSibling;
  if (wantBefore !== currentPlaceholderPosition) {
    ul.insertBefore(ph, wantBefore || null);
  }
}

