function positionToPointer(clientY) {
  const { li, ul, ph, grabDy, listRect } = active;
  // Auto-scroll the list near its edges
  if (clientY > listRect.bottom - 70) ul.scrollTop += 10;
  else if (clientY < listRect.top + 70) ul.scrollTop -= 10;

  // Convert pointer into local (content) coordinates
  const localY = clientY - listRect.top - grabDy;
  const maxTop = Math.max(0, ul.scrollHeight - li.offsetHeight);
  const top = Math.max(0, Math.min(localY, maxTop));
  li.style.top = top + "px";

  // Hit-test using content offsets of the placeholder and siblings (in flow)
  const centerLocal = top + li.offsetHeight / 2;
  const inFlow = Array.from(ul.querySelectorAll(":scope > li, :scope > div.is-placeholder"))
                      .filter(x => x !== li);
  let target = null;
  for (const r of inFlow) {
    const rTop = r.offsetTop;
    const rMid = rTop + r.offsetHeight / 2;
    if (centerLocal < rMid) { target = r; break; }
  }
  // `target` is the element that should immediately follow the placeholder.
  if (ph.nextSibling !== target) {
    if (target) ul.insertBefore(ph, target);
    else ul.appendChild(ph);
  }
}

